import{_ as u,C as o,o as d,c as w,j as t,a,E as s,a8 as m}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/BOWYujhIQuo-640.webp",g="/schedule-dashboard/thumbs/yt/BOWYujhIQuo-1280.webp",r="/schedule-dashboard/thumbs/yt/kiClTcJUnhc-640.webp",b="/schedule-dashboard/thumbs/yt/kiClTcJUnhc-1280.webp",i="/schedule-dashboard/thumbs/yt/Fva8hFosqyQ-640.webp",v="/schedule-dashboard/thumbs/yt/Fva8hFosqyQ-1280.webp",l="/schedule-dashboard/thumbs/yt/hJz7zi17mXA-640.webp",f="/schedule-dashboard/thumbs/yt/hJz7zi17mXA-1280.webp",h="/schedule-dashboard/thumbs/yt/Y5utTIuUNg4-640.webp",y="/schedule-dashboard/thumbs/yt/Y5utTIuUNg4-1280.webp",M=JSON.parse('{"title":"AI Digest · Sat 17 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-17","routine":"digest"},"relativePath":"digest/2026-10-17.md","filePath":"digest/[date].md"}'),k={name:"digest/2026-10-17.md"},_=n+" 640w, "+g+" 1280w",A=r+" 640w, "+b+" 1280w",T=i+" 640w, "+v+" 1280w",J=l+" 640w, "+f+" 1280w",C=h+" 640w, "+y+" 1280w",I={id:"ai-digest-·-sat-17-oct-2026",tabindex:"-1"};function x(z,e,O,S,F,Q){const c=o("Badge"),p=o("DayFilter");return d(),w("div",null,[t("h1",I,[e[0]||(e[0]=a("AI Digest · Sat 17 Oct 2026 ",-1)),s(c,{type:"tip",text:"5"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sat-17-oct-2026","aria-label":'Permalink to "AI Digest · Sat 17 Oct 2026 <Badge type="tip" text="5" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack, last 24h (17 Oct 2026) · run date Sat 17 Oct 2026 · 5 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer"),a(" posted 3 videos (about 2.1 hours). The freshest is Apollo and Rowspace's fireside chat on cutting 2–3-day CLO portfolio builds to minutes. The big one is Anthropic's 1h41m workshop launching "),t("strong",null,"Flows"),a(` in Claude Managed Agents, where Claude runs up to 1,000 agents per flow. Flows and the failure-modes section are new, but its security half mostly repeats the 12 Oct Managed Agents series. swyx's 7-minute "Highest Loop" welcome keynote is light.`)]),t("p",null,[t("strong",null,"Better Stack"),a(" posted 2 videos. The freshest is a careful test of Nokia's AnyJev, a free decision-model library, against Jev on 500 Onion-vs-real headlines; it isn't a repeat, since decision models have only come up once before. The other is a 5-minute browser-fingerprinting explainer. That one had no transcript, so its entry is built from chapters and description only.")])],-1)),s(p),e[5]||(e[5]=m('<div class="grid cards2"><article class="it full" id="v-BOWYujhIQuo" data-title="AI Agents Cut 3-Day Portfolio Builds to Minutes — Jack McDonald, Apollo &amp; Michael Manapat, Rowspace" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=BOWYujhIQuo" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+_+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=BOWYujhIQuo" target="_blank" rel="noopener">AI Agents Cut 3-Day Portfolio Builds to Minutes — Jack McDonald, Apollo &amp; Michael Manapat, Rowspace</a></h3><div class="meta">AI Engineer · Jack McDonald (Apollo / Redding Ridge) &amp; Michael Manapat (Rowspace) · uploaded 17 Oct, 4:30 AM IST · 19:04</div><div class="verdict v-skim"><b>Verdict:</b> skim from <a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=247s" target="_blank" rel="noopener">4:07</a>: the two concrete workflow examples (3:38–7:00) and the 20-sources point are the substance; the rest is a general fireside chat.</div><div class="sh">Where AI became mission-critical</div><ul><li><strong>Who&#39;s talking:</strong> Redding Ridge is Apollo&#39;s separate structured-credit/CLO manager with about $50B in assets; Rowspace uses agents to do data-engineering work, pulling and reconciling data from many systems so PMs and traders decide faster (<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=105s" target="_blank" rel="noopener">1:45</a>)</li><li><strong>Portfolio builds, days to minutes:</strong> CLOs are rules-based with waterfalls buried in indentures; a PM used to spend 2–3 days in Excel building a 200–400-name mock portfolio. Now it&#39;s minutes, the tool gets it to 80–90% and the PM refines the last 10% (<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=247s" target="_blank" rel="noopener">4:07</a>–<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=331s" target="_blank" rel="noopener">5:31</a>)</li><li><strong>Weekly trade reconciliation automated:</strong> Warehouse purchase/sale recs used to mean 2–3 people logging into bank accounts for hours each week; now the report regenerates in about a minute and the team just QAs it daily (<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=334s" target="_blank" rel="noopener">5:34</a>–<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li></ul><div class="sh">Why not just use ChatGPT or Claude</div><ul><li><strong>Own data, one golden source:</strong> General LLMs work off public info, fine for research. Here one data point can come from 20 sources with only one correct, so Rowspace engineers sit with the PM and finance teams daily to pin down calculations across order management, performance systems and Bloomberg (<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=560s" target="_blank" rel="noopener">9:20</a>)</li><li><strong>AI-native before Claude Code:</strong> Manapat says Apollo was pushing &quot;platform, not point solutions&quot; back when Cursor was still tab completion; McDonald credits a flat, adopt-don&#39;t-dismiss culture (<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=560s" target="_blank" rel="noopener">9:20</a>–<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=690s" target="_blank" rel="noopener">11:30</a>)</li></ul><div class="sh">Where finance is and what&#39;s next</div><ul><li><strong>Still early:</strong> McDonald thinks institutional finance is early. Research summarization is lower value for now, though junior support may shrink; the real win is freeing capacity from routine work (<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=690s" target="_blank" rel="noopener">11:30</a>–<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=800s" target="_blank" rel="noopener">13:20</a>)</li><li><strong>Durable edge, not just Excel:</strong> He argues AI becomes a lasting advantage in private markets because accurate, trusted information drives the process, and mistakes flow down to 400+ global investors (<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=827s" target="_blank" rel="noopener">13:47</a>–<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=1020s" target="_blank" rel="noopener">17:00</a>)</li><li><strong>Advice for builders:</strong> Odd-looking processes usually exist for a reason, so put &quot;boots on the ground&quot; with the front office; that&#39;s why Rowspace is ahead of its roadmap (<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=1080s" target="_blank" rel="noopener">18:00</a>–<a href="https://www.youtube.com/watch?v=BOWYujhIQuo&amp;t=1140s" target="_blank" rel="noopener">19:00</a>)</li></ul></div></article><article class="it full" id="v-kiClTcJUnhc" data-title="Why One AI Agent Isn’t Enough (And How to Run 1,000) - CJ Avilla &amp; Harrison Stall, Anthropic" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=kiClTcJUnhc" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+A+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=kiClTcJUnhc" target="_blank" rel="noopener">Why One AI Agent Isn’t Enough (And How to Run 1,000) - CJ Avilla &amp; Harrison Stall, Anthropic</a></h3><div class="meta">AI Engineer · CJ Avilla &amp; Harrison Stall, Anthropic · uploaded 17 Oct, 12:30 AM IST · 1:41:44</div><div class="verdict v-skim"><b>Verdict:</b> skim from <a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=420s" target="_blank" rel="noopener">7:00</a>: watch the Flows pitch and demo (7:00–32:15) and the failure-modes section (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=4335s" target="_blank" rel="noopener">1:12:15</a>); skip the long Q&amp;A unless you&#39;re building on CMA, and the security half is largely repeat.</div><div class="repeat">🔁 Repeat: &#39;Claude Managed Agents&#39; — seen 4 times before. New here: the brand-new <strong>Flows</strong> feature, where Claude plans its own multi-agent topology of up to 1,000 agents via the API.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 10 times before. New here: a clear explanation of why single agents fail (laziness, self-preference bias, goal drift) and how phase-by-phase fan-out avoids it.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 17 times before. New here: budgets with pause-and-resume, `user.interrupt`, and auto mode as the default advice.</div><div class="repeat">🔁 Repeat: &#39;secrets management&#39; — seen 5 times before. Mostly the same vault and egress-proxy credential injection covered in the 12 Oct CMA series; the Twilio walkthrough is the only new part.</div><div class="sh">Why one agent isn&#39;t enough</div><ul><li><strong>Unix vs. OS/360 vs. Linux:</strong> Thompson built Unix alone in a month; OS/360 needed ~1,000 engineers and produced <em>The Mythical Man-Month</em>; Linux 7.2 took 9 weeks with ~2,600 developers from 300 companies, after Linus &quot;didn&#39;t scale&quot; in 1998 and moved to layers of trusted maintainers. The pitch is that agent orchestration hits the same wall (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=357s" target="_blank" rel="noopener">5:57</a>)</li><li><strong>Rough limits by setup:</strong> One agent lasts about an hour; a coordinator plus roster lasts a bit longer; dynamic workflows (nested, parallel agents) are what handle truly hard tasks. Teams hand-rolling this struggle with container restarts, one coordinator tracking ~60 agents, and no way to see the agent graph (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=545s" target="_blank" rel="noopener">9:05</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=780s" target="_blank" rel="noopener">13:00</a>)</li></ul><div class="sh">What Flows is and the demo</div><ul><li><strong>Flows in Claude Managed Agents:</strong> Announced &quot;Friday&quot;, it&#39;s the API version of Claude Code&#39;s ultra code dynamic workflows. A lead agent writes a plan, fans out per phase into isolated contexts, streams every event on one feed, and takes session budgets and API interrupts. It replaces May&#39;s &quot;multi-agent V1&quot;, where you had to define every subagent yourself (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=1020s" target="_blank" rel="noopener">17:00</a>)</li><li><strong>Stock watchlist scanner:</strong> Console template on Opus 5.5 with the `multi-agent 2026-10-01` type; one scan agent per ticker, then an isolated review phase. A flow costs much more than a single agent but finds far more detail. You can steer compute per phase in the prompt, for example two Haiku scanners per ticker and two or three Fable reviewers (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=1123s" target="_blank" rel="noopener">18:43</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=1800s" target="_blank" rel="noopener">30:00</a>)</li><li><strong>Getting started:</strong> Templates are also bundled in the Claude API skill in Claude Code and driven through the Ant CLI. Loose, open-ended first prompts work best. Max 5x subscriptions now include about $100/month in API credits and Teams up to $500 (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=1800s" target="_blank" rel="noopener">30:00</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=1935s" target="_blank" rel="noopener">32:15</a>)</li></ul><div class="sh">Q&amp;A highlights</div><ul><li><strong>Tuning and limits:</strong> The hill-climb skill (`/claude-api hill climb`, inspired by Karpathy&#39;s autoresearch) iterates on prompts, and Dreaming improves memory across sessions. Claude isn&#39;t told its budget because it &quot;gets a little anxious&quot;; hitting the cap pauses the flow and raising it resumes without redoing work. Subagents talk only through a shared file system, nesting is one layer deep, and private MCP servers are reached through Cloudflare-based MCP tunnels (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=2100s" target="_blank" rel="noopener">35:00</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=2560s" target="_blank" rel="noopener">42:40</a>)</li><li><strong>1,000-agent OS run:</strong> CJ asked a flow to build a Unix-compatible OS with a Python interpreter using up to 1,000 agents. After 85 hours it was 3–4 flows in with about 1,000 commits, and a Sonnet docs-writer team documents each phase (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=2740s" target="_blank" rel="noopener">45:40</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=2880s" target="_blank" rel="noopener">48:00</a>) <a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=3231s" target="_blank" rel="noopener">53:51</a></li></ul><div class="sh">Templates and why single agents fail</div><ul><li><strong>Bug Hunter and Explainer Studio:</strong> Bug Hunter slices a PR, reviews each slice in isolation, cross-checks the findings, then a prover agent reproduces bugs and posts prioritized inline comments. Explainer Studio runs research, fact-check, brief, scene and animation phases to make @ClaudeDevs launch videos that used to take about 20 hours (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=3840s" target="_blank" rel="noopener">1:04:00</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=4320s" target="_blank" rel="noopener">1:12:00</a>)</li><li><strong>Three single-agent failure modes:</strong> <em>Laziness</em> (after 35 of 50 services look healthy it stops checking), <em>self-preferential bias</em> (it grades its own work as good), and <em>goal drift</em> (a &quot;don&#39;t touch prod&quot; instruction gets lost through compaction). Flows fix this with one agent per item, isolated adversarial reviewers, and the goal copied into every subagent (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=4335s" target="_blank" rel="noopener">1:12:15</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=4580s" target="_blank" rel="noopener">1:16:20</a>)</li></ul><div class="sh">Running agents safely at scale</div><ul><li><strong>Declare, contain, detect:</strong> Six risks (prompt injection, credential leaks, exfiltration, overreach, tool misuse, low visibility). The brain (harness plus session) is kept separate from the hands (sandbox and tools). Sandboxes only ever see fake secrets; the egress proxy swaps in real ones, and only for allow-listed hosts (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=4640s" target="_blank" rel="noopener">1:17:20</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=5040s" target="_blank" rel="noopener">1:24:00</a>) (repeat)</li><li><strong>Concrete controls:</strong> Set a budget (e.g. $1.25) paired with Outcomes rubrics, stop runs with a `user.interrupt` event, and have an agent audit last week&#39;s session logs. Switch from always-ask to auto mode, since people click approve about 97% of the time. Store keys like Twilio&#39;s in vaults with an injection location and allowed hosts, disable web fetch/search and MCP tools one by one, and lock environment egress to `api.twilio.com` (<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=5040s" target="_blank" rel="noopener">1:24:00</a>–<a href="https://www.youtube.com/watch?v=kiClTcJUnhc&amp;t=5520s" target="_blank" rel="noopener">1:32:00</a>)</li></ul></div></article><article class="it full" id="v-Fva8hFosqyQ" data-title="The Highest Loop — swyx" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=Fva8hFosqyQ" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=Fva8hFosqyQ" target="_blank" rel="noopener">The Highest Loop — swyx</a></h3><div class="meta">AI Engineer · swyx (AI Engineer organizer) · uploaded 16 Oct, 7:33 AM IST · 7:20</div><div class="verdict v-skim"><b>Verdict:</b> skip, or skim from <a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=60s" target="_blank" rel="noopener">1:00</a>: a short welcome keynote with little technical content beyond the loop-level framing.</div><div class="sh">Loops as the core skill</div><ul><li><strong>From tokens to loops:</strong> First minute is music. Then the history goes token, chat, tools, goals, and now automations, cron jobs and loops. swyx points to his <em>Loopcraft</em> essay and says the core AI-engineer skill is knowing which loop you&#39;re in: go up a loop to scale productivity, down a loop to fix reliability. &quot;Literally just a stack of while loops&quot; (<a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=65s" target="_blank" rel="noopener">1:05</a>–<a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=200s" target="_blank" rel="noopener">3:20</a>)</li><li><strong>The human loop:</strong> A parallel from heartbeat to talking, tools, work and tiny teams, out to civilization-scale collective intelligence; coding agents are now spreading beyond code (<a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=200s" target="_blank" rel="noopener">3:20</a>–<a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=280s" target="_blank" rel="noopener">4:40</a>)</li></ul><div class="sh">Conference notes</div><ul><li><strong>Vertical tracks and growth:</strong> This year adds AI in healthcare, finance, GTM and a forward-deployed engineering track. Ticket sales went from roughly linear in 2023 to about 2,000 people in 2024; they aimed for 6,000 this year and crossed 7,000 (<a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=280s" target="_blank" rel="noopener">4:40</a>–<a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li><li><strong>&quot;The highest loop&quot;:</strong> Humans gathering to decide what the next loop should be. Summits are planned in New York, Paris, Singapore, Melbourne and Miami, and a partnerships team is being hired for local summits (<a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=Fva8hFosqyQ&amp;t=425s" target="_blank" rel="noopener">7:05</a>)</li></ul></div></article><article class="it full" id="v-hJz7zi17mXA" data-title="Nokia Just Released a Free Jev Alternative (AnyJev)" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=hJz7zi17mXA" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+J+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=hJz7zi17mXA" target="_blank" rel="noopener">Nokia Just Released a Free Jev Alternative (AnyJev)</a></h3><div class="meta">Better Stack · Andrus, Better Stack · uploaded 16 Oct, 10:11 PM IST · 15:40</div><div class="verdict v-worth"><b>Verdict:</b> worth watching if you use LLMs as classifiers; the calibration and lean-overshoot findings are the useful part, beyond the &quot;free Jev&quot; framing.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 39 times before. New here: a training-free library that turns any open-weight model into a Jev-style decision model.</div><div class="repeat">🔁 Repeat: &#39;LLM releases / benchmarks&#39; — seen 35 times before. New here: a careful satire-vs-real benchmark that checks calibration and option-order flips, not just accuracy. Decision models came up once before, in the 5 Oct Cloudflare Clef vs Jev test.</div><div class="sh">What AnyJev does</div><ul><li><strong>Three models, three answers:</strong> On a real headline, raw Qwen says 99% satire, Jev says 58% real, and Qwen plus AnyJev says 100% real. AnyJev comes from Nokia&#39;s applied research team and claims to make any open model a decision model with no training or labelled data (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=103s" target="_blank" rel="noopener">1:43</a>)</li><li><strong>Decision models vs Jev pricing:</strong> You give it a state and a typed question and get a probability per option, with no text to parse. Jev is hosted and closed at 4.2¢ per million input tokens with free output; about 310 tokens per call means roughly 1¢ per 1,000 calls. AnyJev is Apache 2.0 and works with Transformers, vLLM, SGLang and llama.cpp (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=103s" target="_blank" rel="noopener">1:43</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=177s" target="_blank" rel="noopener">2:57</a>)</li><li><strong>How it works and L0:</strong> Options get letters and it reads the next-token probability of each letter, so parsing can&#39;t fail. Level L0 removes position bias by averaging over every option order and removes label bias by dividing out the model&#39;s lean, using either a &quot;batch prior&quot; or a &quot;content-free prior&quot; for single inputs (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=177s" target="_blank" rel="noopener">2:57</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=335s" target="_blank" rel="noopener">5:35</a>)</li><li><strong>Order-flip test:</strong> Swapping the order of the options flipped raw Qwen on 20 of 500 headlines (4%) and Jev on 18 (small moves of about 3 points). L0 flipped zero (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=234s" target="_blank" rel="noopener">3:54</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=289s" target="_blank" rel="noopener">4:49</a>)</li></ul><div class="sh">The 500-headline benchmark</div><ul><li><strong>Setup and speed:</strong> 500 headlines (half Onion, half HuffPost) from Kaggle&#39;s 28,619-headline sarcasm set. Jev 1.13 finished all 500 in 51 seconds over the network; Qwen3-8B with and without L0 on an M2 Max took about 4:36 (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=335s" target="_blank" rel="noopener">5:35</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=429s" target="_blank" rel="noopener">7:09</a>)</li><li><strong>Scores:</strong> Jev 80% accuracy, raw Qwen 68.4%, L0 68.6%, so Jev wins by about 12 points on accuracy, calibration and speed for under a cent. Qwen called about 69% of headlines satire; the content-free prior removes that lean but lands at 66.6% (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=429s" target="_blank" rel="noopener">7:09</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>Confidence means little locally:</strong> 87% of raw Qwen&#39;s answers were at 99%+ confidence, yet 30% of those were wrong. Calibration error is about 0.3 for Qwen and L0 versus 0.07 for Jev, and L0 doesn&#39;t claim to calibrate (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=587s" target="_blank" rel="noopener">9:47</a>)</li></ul><div class="sh">Hand-picked rounds and takeaway</div><ul><li><strong>Real news that sounds fake:</strong> On 7 real plus 3 Onion headlines, AnyJev scored 70%, Jev 50% and raw Qwen 40%; L0 fixed 4 answers and broke one (the GTA 6 Randy Newman joke) (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=587s" target="_blank" rel="noopener">9:47</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=700s" target="_blank" rel="noopener">11:40</a>)</li><li><strong>Fresh headlines reverse it:</strong> On 10 recent 50/50 headlines, Jev scored 90%, raw Qwen 80% and AnyJev 60%, because removing the satire lean overshot. Verdict: good for private data that stays on your machine, but it doesn&#39;t make the model smarter; higher levels that calibrate need a few hundred labelled examples (untested). Not sold yet (<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=700s" target="_blank" rel="noopener">11:40</a>–<a href="https://www.youtube.com/watch?v=hJz7zi17mXA&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li></ul></div></article><article class="it full" id="v-Y5utTIuUNg4" data-title="Even a VPN Can&#39;t Hide You From This (Browser Fingerprinting)" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=Y5utTIuUNg4" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+C+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=Y5utTIuUNg4" target="_blank" rel="noopener">Even a VPN Can&#39;t Hide You From This (Browser Fingerprinting)</a></h3><div class="meta">Better Stack · Better Stack · uploaded 16 Oct, 12:00 PM IST · 5:13</div><div class="verdict v-skim"><b>Verdict:</b> skim: a short privacy explainer. The details above come only from the description and chapter titles.</div><p class="note"><em>No transcript available yet; this entry is built from the video&#39;s chapters and description only.</em></p><div class="sh">How fingerprinting works</div><ul><li><strong>Cookies, incognito and VPN aren&#39;t enough:</strong> Per the description, a site can still recognise you from screen, timezone, canvas and audio quirks, which combine into an ID you can&#39;t delete. The video uses its own demo page to show this <a href="https://www.youtube.com/watch?v=Y5utTIuUNg4&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=Y5utTIuUNg4&amp;t=26s" target="_blank" rel="noopener">0:26</a></li><li><strong>Cookies vs fingerprints, &quot;20 questions&quot;:</strong> Chapters cover how a fingerprint differs from a cookie and how browser APIs answer a series of questions that narrow you down <a href="https://www.youtube.com/watch?v=Y5utTIuUNg4&amp;t=62s" target="_blank" rel="noopener">1:02</a>–<a href="https://www.youtube.com/watch?v=Y5utTIuUNg4&amp;t=87s" target="_blank" rel="noopener">1:27</a></li><li><strong>Canvas and audio fingerprinting:</strong> A chapter on rendering-based and audio-stack fingerprints <a href="https://www.youtube.com/watch?v=Y5utTIuUNg4&amp;t=132s" target="_blank" rel="noopener">2:12</a></li></ul><div class="sh">Real-world use and defence</div><ul><li><strong>FingerprintJS and the AliExpress headphones:</strong> A chapter on the commercial FingerprintJS library and an AliExpress example <a href="https://www.youtube.com/watch?v=Y5utTIuUNg4&amp;t=171s" target="_blank" rel="noopener">2:51</a></li><li><strong>Test your browser and avoid it:</strong> Suggests checking your own browser on <a href="https://coveryourtracks.eff.org" target="_blank" rel="noopener">Cover Your Tracks</a> and comparing which browsers actually block fingerprinting; the demo code is linked as a gist <a href="https://www.youtube.com/watch?v=Y5utTIuUNg4&amp;t=203s" target="_blank" rel="noopener">3:23</a>–<a href="https://www.youtube.com/watch?v=Y5utTIuUNg4&amp;t=237s" target="_blank" rel="noopener">3:57</a></li></ul></div></article></div>',1))])}const U=u(k,[["render",x]]);export{M as __pageData,U as default};
